# Typical RFC 1918 usage in a VPC definition
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"   # inside 10.0.0.0/8
}
# home router LAN: 192.168.0.0/24
# corporate: 172.16.0.0 - 172.31.255.255

# NGINX (Layer 7) routing by path
location /api/ { proxy_pass http://api_pool; }
location /static/ { proxy_pass http://cdn_pool; }
# an L4 balancer cannot see the URL to make this choice
